/**
 * Cloud-native data, YAML only (0.9, ml-cnv.1 / .3 / .5) — browser
 * verification, which is also the demo (examples/verification/cloud-native/).
 *
 * @remarks
 * Fixtures: synthetic, CC0, generated by scripts/fixtures/cloud-native.py
 * into docs/public/gallery-assets/cloud-native/, served by e2e/server.mjs
 * with HTTP range support (and its /norange/, /nocors/, /oversize/ variants
 * for the failure cases). Runs on every maplibre-gl leg of the CI matrix
 * (4/5/6); nothing here is version-gated — PMTiles and FlatGeobuf need
 * maplibre-gl 4+, the floor of that matrix.
 */
import { test, expect, type Page } from "@playwright/test";
import { PNG } from "pngjs";

/** Fail on page errors and off-origin requests (hermeticity). */
async function guard(page: Page, allow: RegExp = /^$/): Promise<string[]> {
  const errors: string[] = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route("**/*", (route) => {
    const url = route.request().url();
    if (/^https?:\/\/(localhost|127\.0\.0\.1)[:/]/.test(url) || /^(data|blob):/.test(url) || allow.test(url)) {
      return route.continue();
    }
    errors.push(`external request (suite must stay hermetic): ${url}`);
    return route.abort();
  });
  return errors;
}

/** Record every response for a file name: status codes, and whether a Range was sent. */
function recordRequests(page: Page, name: RegExp) {
  const seen: { url: string; status: number; range: string | undefined }[] = [];
  page.on("response", (r) => {
    if (name.test(r.url())) seen.push({ url: r.url(), status: r.status(), range: r.request().headers()["range"] });
  });
  return seen;
}

/** Wait until a map element's source has rendered features. */
async function waitForFeatures(page: Page, mapId: string, source: string, sourceLayer?: string) {
  await page.waitForFunction(
    ({ mapId, source, sourceLayer }) => {
      const map = (document.getElementById(mapId) as any)?.getMap?.();
      if (!map || !map.getSource(source)) return false;
      const opts = sourceLayer ? { sourceLayer } : undefined;
      return map.querySourceFeatures(source, opts).length > 0;
    },
    { mapId, source, sourceLayer },
    { timeout: 45_000 }
  );
}

test.describe("cloud-native data: PMTiles and FlatGeobuf with no page JavaScript", () => {
  test("v1 and v2 documents render PMTiles (vector + raster) and FlatGeobuf alike", async ({ page }) => {
    const errors = await guard(page);
    const pmtiles = recordRequests(page, /\.pmtiles/);
    const fgb = recordRequests(page, /points\.fgb/);
    await page.goto("/examples/verification/cloud-native/formats.html", { waitUntil: "domcontentloaded" });

    for (const id of ["v1", "v2"]) {
      await page.evaluate((id) => (document.getElementById(id) as any).mapReady(), id);
      await waitForFeatures(page, id, "districts");
      await waitForFeatures(page, id, "outlines", "districts");
      await page.waitForFunction(
        (id) => {
          const map = (document.getElementById(id) as any).getMap();
          return map.isSourceLoaded("imagery") && map.areTilesLoaded();
        },
        id,
        { timeout: 45_000 }
      );
    }

    const state = await page.evaluate(() =>
      ["v1", "v2"].map((id) => {
        const map = (document.getElementById(id) as any).getMap();
        const distinct = (s: string, o?: object) =>
          new Set(map.querySourceFeatures(s, o).map((f: any) => f.properties.name ?? f.properties.id)).size;
        return {
          id,
          districts: distinct("districts"),
          outlines: distinct("outlines", { sourceLayer: "districts" }),
          points: map.querySourceFeatures("points").length,
          zoom: map.getZoom(),
          center: map.getCenter().toArray(),
          imagerySpec: map.getStyle().sources.imagery,
          outlinesSpec: map.getStyle().sources.outlines,
          notice: document.querySelector(`#${id} .ml-map-notice`)?.textContent ?? null,
          legend: document.querySelector(`#${id} .maplibre-yaml-legend, #${id} [class*="legend"]`)?.textContent ?? "",
        };
      })
    );
    for (const s of state) {
      // Every district decoded from the FlatGeobuf file, and drawn from the PMTiles archive.
      expect(s.districts, `${s.id} districts`).toBe(48);
      expect(s.outlines, `${s.id} outlines`).toBeGreaterThan(0);
      // The PMTiles URL reached MapLibre in its canonical absolute pmtiles:// form.
      expect(s.imagerySpec.url).toMatch(/^pmtiles:\/\/http:\/\/localhost:\d+\/gallery-assets\/cloud-native\/imagery\.pmtiles$/);
      expect(s.outlinesSpec.url).toMatch(/^pmtiles:\/\/http:\/\/localhost:\d+\/gallery-assets\/cloud-native\/districts\.pmtiles$/);
      // fitTo framed the decoded FlatGeobuf data (the authored zoom was 8).
      expect(s.zoom, `${s.id} zoom`).toBeGreaterThan(9);
      expect(Math.abs(s.center[0] - 10.2)).toBeLessThan(0.05);
      expect(Math.abs(s.center[1] - 42.15)).toBeLessThan(0.05);
      // Below the viewport source's minzoom (11), nothing is read for it.
      expect(s.points, `${s.id} points below minzoom`).toBe(0);
      expect(s.notice, `${s.id} notice`).toBeNull();
      expect(s.legend).toContain("Districts (FlatGeobuf)");
    }

    // PMTiles were read with range requests only (206), never whole.
    expect(pmtiles.length).toBeGreaterThan(0);
    for (const r of pmtiles) {
      expect(r.range, r.url).toBeTruthy();
      expect(r.status, r.url).toBe(206);
    }

    // A district's popup, from the FlatGeobuf feature's properties.
    const at = await page.evaluate(() => {
      const map = (document.getElementById("v1") as any).getMap();
      const f = map.querySourceFeatures("districts")[0];
      const ring = f.geometry.coordinates[0];
      const xs = ring.map((c: number[]) => c[0]);
      const ys = ring.map((c: number[]) => c[1]);
      const lng = (Math.min(...xs) + Math.max(...xs)) / 2;
      const lat = (Math.min(...ys) + Math.max(...ys)) / 2;
      const p = map.project([lng, lat]);
      const rect = map.getCanvas().getBoundingClientRect();
      return { x: rect.left + p.x, y: rect.top + p.y };
    });
    await page.mouse.click(at.x, at.y);
    await expect(page.locator("#v1 .maplibregl-popup")).toContainText("District");
    await expect(page.locator("#v1 .maplibregl-popup")).toContainText("Population");
    await page.screenshot({ path: "e2e/results/cnv_formats.png" });

    // Read by view: zoom past minzoom and only the points in view arrive,
    // through range requests (the spatial index), not the whole file.
    await page.evaluate(() => {
      for (const id of ["v1", "v2"]) {
        (document.getElementById(id) as any).getMap().jumpTo({ center: [10.1, 42.1], zoom: 13 });
      }
    });
    for (const id of ["v1", "v2"]) await waitForFeatures(page, id, "points");
    const counts = await page.evaluate(() =>
      ["v1", "v2"].map((id) => {
        const map = (document.getElementById(id) as any).getMap();
        return new Set(map.querySourceFeatures("points").map((f: any) => f.properties.id)).size;
      })
    );
    for (const n of counts) {
      expect(n).toBeGreaterThan(0);
      expect(n).toBeLessThan(400);
    }
    expect(fgb.length).toBeGreaterThan(0);
    for (const r of fgb) expect(r.status, `${r.url} ${r.range}`).toBe(206);
    await page.screenshot({ path: "e2e/results/cnv_viewport.png" });

    expect(errors).toEqual([]);
  });

  test("fitTo on a FlatGeobuf file: the first frame is already framed, one request (ml-aot.75 seam)", async ({
    page,
  }) => {
    const errors = await guard(page);
    let requests = 0;
    await page.route("**/gallery-assets/cloud-native/districts.fgb", async (route) => {
      requests += 1;
      await new Promise((resolve) => setTimeout(resolve, 400)); // slow, but inside the fitTo wait
      await route.continue();
    });
    await page.goto("/examples/verification/cloud-native/fit-framed.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await waitForFeatures(page, "map", "districts");
    await page.waitForFunction(() => !(document.getElementById("map") as any).getMap().isMoving());
    const f = await page.evaluate(() => (window as any).__frames);
    expect(f.first, "no first frame recorded").not.toBeNull();
    // The document says [0, 0] z1; the first frame is already on the districts.
    expect(Math.abs(f.first.lng - 10.2), JSON.stringify(f.first)).toBeLessThan(0.05);
    expect(Math.abs(f.first.lat - 42.15), JSON.stringify(f.first)).toBeLessThan(0.05);
    expect(f.first.zoom).toBeGreaterThan(9);
    expect(f.moves).toBe(0);
    expect(requests).toBe(1);
    expect(errors).toEqual([]);
  });

  test("classify: over a FlatGeobuf source computes its breaks from the decoded features", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/classify.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await waitForFeatures(page, "map", "districts");
    await page.waitForFunction(() => {
      const map = (document.getElementById("map") as any).getMap();
      const color = map.getPaintProperty("population", "fill-color");
      return Array.isArray(color) && JSON.stringify(color).includes("population");
    });
    const colors = await page.evaluate(() =>
      JSON.stringify((document.getElementById("map") as any).getMap().getPaintProperty("population", "fill-color"))
    );
    expect(colors).toMatch(/"step"/);
    await expect(page.locator("#map .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/cnv_classify.png" });
    expect(errors).toEqual([]);
  });

  test("a page that registered its own pmtiles protocol keeps it (host wins)", async ({ page }) => {
    const errors = await guard(page);
    const archive = recordRequests(page, /districts\.pmtiles/);
    await page.goto("/examples/verification/cloud-native/host-protocol.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await waitForFeatures(page, "map", "districts", "host");
    const state = await page.evaluate(async () => {
      const gl = (await import("/packages/core/maplibre.js" as string)).default as any;
      return {
        calls: (window as any).hostCalls,
        same: gl.config.REGISTERED_PROTOCOLS.pmtiles === (window as any).hostHandler,
        notice: document.querySelector("#map .ml-map-notice")?.textContent ?? null,
      };
    });
    expect(state.calls).toBeGreaterThan(0);
    expect(state.same).toBe(true);
    expect(state.notice).toBeNull();
    // Core's own handler never ran: nothing fetched the archive itself.
    expect(archive).toEqual([]);
    await page.screenshot({ path: "e2e/results/cnv_host_protocol.png" });
    expect(errors).toEqual([]);
  });

  test("every failure is explained on the map in plain words", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/errors.html", { waitUntil: "domcontentloaded" });
    for (const id of ["pmtiles-errors", "fgb-errors", "reserved", "fallbacks"]) {
      await page.evaluate((id) => (document.getElementById(id) as any).mapReady(), id);
    }

    const pmtiles = page.locator("#pmtiles-errors .ml-map-notice");
    await expect(pmtiles).toContainText(
      "Source norange didn't load: /norange/gallery-assets/cloud-native/districts.pmtiles was served " +
        "without range-request support (the server sent the whole file instead of the part asked for)."
    );
    await expect(pmtiles).toContainText(
      "GitHub Pages, Netlify, Cloudflare, S3 and R2 do; python -m http.server does not — preview locally " +
        "with npx serve instead."
    );
    await expect(pmtiles).toContainText(/Source blocked didn't load: The browser couldn't read http:\/\/127\.0\.0\.1:\d+\/nocors\/gallery-assets\/cloud-native\/districts\.pmtiles: the server didn't allow this page to load it \(CORS\)/);
    await expect(pmtiles).toContainText(
      "Source webpage didn't load: /gallery-assets/cloud-native/not-really.pmtiles isn't a PMTiles file. " +
        "A wrong path often returns a web page instead — check the file name and folder."
    );
    await expect(pmtiles).toContainText(
      "Source missing didn't load: /gallery-assets/cloud-native/missing.pmtiles didn't load (404 Not Found)."
    );

    const fgb = page.locator("#fgb-errors .ml-map-notice");
    await expect(fgb).toContainText(/Layer blocked has no data: The browser couldn't read http:\/\/127\.0\.0\.1:\d+\/nocors\/gallery-assets\/cloud-native\/districts\.fgb: the server didn't allow this page to load it \(CORS\)/);
    await expect(fgb).toContainText(
      "Data file /gallery-assets/cloud-native/missing.fgb didn't load (404 Not Found), so layer missing has no data."
    );
    await expect(fgb).toContainText(
      "Layer webpage has no data: /gallery-assets/cloud-native/not-really.fgb isn't a FlatGeobuf file."
    );
    await expect(fgb).toContainText(
      "Layer mercator has no data: /gallery-assets/cloud-native/districts-3857.fgb is in EPSG:3857; MapLibre " +
        "needs longitude/latitude (EPSG:4326). Reproject it: ogr2ogr -t_srs EPSG:4326 out.fgb districts-3857.fgb."
    );
    await expect(fgb).toContainText(
      "Layer huge has no data: /oversize/60/gallery-assets/cloud-native/points-noindex.fgb is 60 MB, too large " +
        "to load whole in a browser."
    );
    await expect(fgb).toContainText(
      "Layer unindexed has no data: /gallery-assets/cloud-native/points-noindex.fgb has no spatial index"
    );

    const reserved = page.locator("#reserved .ml-map-notice");
    await expect(reserved).toContainText(
      "Layer wells has no data: /gallery-assets/cloud-native/wells.parquet is a GeoParquet file, which this " +
        "version of maplibre-yaml can't read yet (it's planned)."
    );
    await expect(reserved).toContainText(
      "Source scene didn't load: /gallery-assets/cloud-native/scene.tif is a Cloud Optimized GeoTIFF (COG), " +
        "which this version of maplibre-yaml can't read on its own yet (it's planned)."
    );
    // The rest of a map with a failed source still draws.
    await waitForFeatures(page, "reserved", "districts");
    // ...and the COG's placeholder draws nothing: away from the districts the
    // map shows the basemap's own background (#cfe8c9).
    const box = (await page.locator("#reserved").boundingBox())!;
    await page.waitForTimeout(500);
    const shot = PNG.sync.read(
      await page.screenshot({ clip: { x: box.x + 8, y: box.y + box.height - 60, width: 4, height: 4 } })
    );
    const [r, g, b] = [shot.data[0]!, shot.data[1]!, shot.data[2]!];
    expect(Math.abs(r - 0xcf) + Math.abs(g - 0xe8) + Math.abs(b - 0xc9), `pixel ${r},${g},${b}`).toBeLessThan(12);

    // Never a raw library message.
    for (const id of ["pmtiles-errors", "fgb-errors", "reserved"]) {
      const text = (await page.locator(`#${id} .ml-map-notice`).textContent()) ?? "";
      expect(text).not.toMatch(/magic number|Failed to fetch|content-length|Byte Serving|Not a FlatGeobuf|Bad response code|Unexpected token/i);
    }

    // The two that must work anyway: no ranges → read whole; too large but
    // indexed → read by view.
    await waitForFeatures(page, "fallbacks", "norange");
    await waitForFeatures(page, "fallbacks", "big");
    await expect(page.locator("#fallbacks .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/cnv_errors.png", fullPage: true });
    expect(errors).toEqual([]);
  });

  test("on a project site, base applies to the file inside pmtiles:// (and to .fgb)", async ({ page }) => {
    const errors = await guard(page);
    const notFound: string[] = [];
    page.on("response", (r) => {
      if (r.status() === 404) notFound.push(new URL(r.url()).pathname);
    });
    await page.goto("/my-repo/blog/cloud-native.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("with-base") as any).mapReady());
    await waitForFeatures(page, "with-base", "districts");
    await waitForFeatures(page, "with-base", "outlines", "districts");
    const spec = await page.evaluate(
      () => (document.getElementById("with-base") as any).getMap().getStyle().sources
    );
    expect(spec.outlines.url).toMatch(/^pmtiles:\/\/http:\/\/localhost:\d+\/my-repo\/cloud-native\/districts\.pmtiles$/);
    expect(spec.imagery.url).toMatch(/^pmtiles:\/\/http:\/\/localhost:\d+\/my-repo\/cloud-native\/imagery\.pmtiles$/);
    await expect(page.locator("#with-base .ml-map-notice")).toHaveCount(0);
    // Without base the same document can't find its files.
    await expect(page.locator("#no-base .ml-map-notice")).toContainText(
      "Source outlines didn't load: /cloud-native/districts.pmtiles didn't load (404 Not Found)."
    );
    expect(notFound.filter((p) => p.startsWith("/my-repo/cloud-native/"))).toEqual([]);
    await page.screenshot({ path: "e2e/results/cnv_base_path.png" });
    expect(errors).toEqual([]);
  });

  test("<ml-scrollytelling> reads PMTiles and FlatGeobuf too", async ({ page }) => {
    const errors = await guard(page);
    await page.goto("/examples/verification/cloud-native/story.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("story") as any).mapReady());
    await page.waitForFunction(
      () => {
        const el = document.querySelector("#story ml-map") as any;
        const map = el?.getMap?.();
        return Boolean(
          map &&
            map.getSource("districts") &&
            map.querySourceFeatures("districts").length > 0 &&
            map.querySourceFeatures("outlines", { sourceLayer: "districts" }).length > 0
        );
      },
      undefined,
      { timeout: 45_000 }
    );
    await expect(page.locator("#story .ml-map-notice")).toHaveCount(0);
    await page.screenshot({ path: "e2e/results/cnv_story.png" });
    expect(errors).toEqual([]);
  });

  test("plain HTML from the CDN build: only maplibre-gl in the import map, nothing extra downloaded", async ({ page }) => {
    const errors = await guard(page);
    const scripts: string[] = [];
    page.on("request", (r) => {
      if (["script"].includes(r.resourceType()) || /\.m?js(\?|$)/.test(r.url())) scripts.push(new URL(r.url()).pathname);
    });
    await page.goto("/examples/verification/cloud-native/cdn.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    await waitForFeatures(page, "map", "districts");
    await waitForFeatures(page, "map", "outlines", "districts");
    await expect(page.locator("#map .ml-map-notice")).toHaveCount(0);
    // The package's own downloads: the entry and the one browser bundle —
    // no decoder chunks in 0.9.
    const fromPackage = [...new Set(scripts.filter((p) => p.startsWith("/cdn/")))].sort();
    expect(fromPackage).toEqual([
      "/cdn/@maplibre-yaml/core@0.9.0/dist/register.browser.js",
      "/cdn/@maplibre-yaml/core@0.9.0/register.js",
    ]);
    await page.screenshot({ path: "e2e/results/cnv_cdn.png" });
    expect(errors).toEqual([]);
  });

  test("a compressed (Zstandard) FlatGeobuf on a CDN page: a plain notice, no module-resolution error (ml-aot.109)", async ({
    page,
  }) => {
    const errors = await guard(page);
    const consoleLines: string[] = [];
    page.on("console", (m) => consoleLines.push(m.text()));
    const zstdRequests: string[] = [];
    page.on("request", (r) => {
      if (/zstd-wasm/.test(r.url())) zstdRequests.push(r.url());
    });
    await page.goto("/examples/verification/cloud-native/cdn-compressed.html", { waitUntil: "domcontentloaded" });
    await page.evaluate(() => (document.getElementById("map") as any).mapReady());
    const notice = page.locator("#map .ml-map-notice");
    await expect(notice).toContainText("districts-zstd.fgb", { timeout: 30_000 });
    await expect(notice).toContainText("is compressed (Zstandard)");
    await expect(notice).toContainText("zstd -d districts-zstd.fgb");
    expect(zstdRequests).toEqual([]);
    expect(consoleLines.filter((l) => /Failed to resolve module specifier|zstd-wasm/.test(l))).toEqual([]);
    expect(errors).toEqual([]);
  });
});
